class BtsStatusInterface21B(object):

    def get_bts_info(self, timeout=20, detailed_output=False):
        """
        Get overall information regarding Node B from M-Plane (OAM).

        :param int timeout: Timeout for the operation.
        :param bool detailed_output: return full request response when True, defaults set to False.
        :return dict: Dictionary structure with data, where Keys are various information categories.
                      More details (content of requestMessage is returned data):
                      https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-getBtsInformation.html
        """
        result = self._api_client.execute_customer_procedure("getBtsInformation", {}, timeout)

        return result if detailed_output else result.get(self._provided_content.request_message)

    def block(self, dist_name=None, timeout=60, detailed_output=False):
        """
        Perform block procedure.

        :param string dist_name: (optional) DEPRECATED. This keyword blocks only the BTS now. If you want to block
         a component, please use dedicated keyword - block_cell, block_all_cells, block_rat, block_gsmtrx.
        :param timeout: (optional) Time to wait for positive procedure result.
        :param bool detailed_output: (optional) return full request response when True, defaults set to False.
        :return Union[list, dict]: Block feedback

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-block.html
        """
        parameters = {}

        if dist_name:
            logging.warning('[DEPRECATION WARNING] This keyword is for blocking just the BTS now.'
                            ' Use cell/hw dedicated blocking keyword')
            parameters = {'distName': dist_name}
            return self._api_client.execute_procedure('block', parameters=parameters, timeout=timeout)

        response = self._api_client.execute_customer_procedure('block', parameters=parameters, timeout=timeout)
        return response if detailed_output else response.get(self._provided_content.request_message)

    def unblock(self, dist_name=None, wait_for_reconnection=True, timeout=60, detailed_output=False):
        """
        Perform unblock procedure.

        :param string dist_name: (optional) DEPRECATED. This keyword unblocks only the BTS now. If you want to unblock
         a component, please use dedicated keyword - unblock_cell, unblock_all_cells, unblock_rat, unblock_gsmtrx.
        :param bool wait_for_reconnection: Should API wait for the reconnection.
        :param timeout: (optional) Time to wait for positive procedure result.
        :param bool detailed_output: (optional) return full request response when True, defaults set to False.
        :return union[str, dict]: Unblock feedback (could be empty)
        More details: https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-unblock.html
        """
        parameters = {'waitForReconnection': wait_for_reconnection}

        if dist_name:
            logging.warning('[DEPRECATION WARNING] This keyword is for unblocking just the BTS now.'
                            ' Use cell/hw dedicated unblocking keyword')
            parameters = {'waitForReconnection': wait_for_reconnection, 'distName': dist_name}
            return self._api_client.execute_procedure('unblock', parameters=parameters, timeout=timeout)

        response = self._api_client.execute_customer_procedure('unblock', parameters=parameters, timeout=timeout)
        return response if detailed_output else response.get(self._provided_content.request_message)

    def get_bts_statuses(self, timeout=10):
        """
        Return all bts statuses.

        :param int timeout: Timeout for the operation.
        :return dict: Dictionary with supported statuses of bts.

        Example

        ::

            {
            u'blockingState': u'Unblocked',
            u'operationalState': u'Disabled',
            u'proceduralState': u'Commissioned'
            }
        """
        bts_info = self.get_bts_info(timeout=timeout)

        bts_statuses = bts_info.get('status')
        if bts_statuses is None:
            error_desc = "Bts statuses information has not been provided by M-Plane."
            raise DataNotAvailable(error_desc)

        return bts_statuses

    def get_cell_specific_info(self, cell_id, timeout=10, detailed_output=False):
        """
        Get information about specific cell, provided by M-plane (OAM).

        :param str cell_id: Id of cell, eg. '/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/NRBTS_R-1/NRCELL_R-1'
        :param int timeout: Timeout for the operation.
        :param bool detailed_output: return full request response when True
        :raise DataNotAvailable: If cell or 5G cell data is not provided by M-Plane.
        :return dict: Dictionary with data for given cell or full api response depends on value detailed_output variable.
        More details (content of requestMessage, cell_id structure):
                        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-getCellById.html
        """
        cell_data = self._api_client.execute_customer_procedure("getCellById", {'id': cell_id}, timeout)
        request_message = cell_data.get(self._provided_content.request_message)

        if request_message is None:
            raise DataNotAvailable("Cell data has not been provided by M-Plane.")

        return cell_data if detailed_output else request_message

    def get_bts_sync_mode(self, timeout=10, detailed_output=False):
        """
        Get bts sync mode information.

        :param int timeout: Timeout for the operation.
        :param bool detailed_output: return full request response when True
        :return dict: dict with getBtsSyncMode feedback or full api response when detailed_output is True
        More details: https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-getBtsSyncMode.html
        """
        bts_sync_mode = self._api_client.execute_customer_procedure(name='getBtsSyncMode', parameters={}, timeout=timeout)
        return bts_sync_mode if detailed_output else bts_sync_mode.get(self._provided_content.request_message)

    def get_cells_info(self, cell_type="nr", timeout=10, detailed_output=False):
        """
        Get information about all cells, provided by M-plane (OAM).
        Currently the returned structures are different for 5G(nr) and 4G.

        :param str cell_type: Cell type of given RAT: "lte", "wcdma", "gsm", "nr" (5G). Default: "nr".
        :param int timeout: Timeout for the operation.
        :param bool detailed_output: return full request response when True
        :raise DataNotAvailable: If cell or 5G (nr) cell data is not provided by M-Plane.
        :return list: List of dictionaries with data for each available cell of given type or full api response
        depends on value detailed_output variable.
                      For example see:
                       https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-getCellList.html


        Example based on current 5G implementation:

        ::

        [{u'band': u'n257',
          u'chBw': u'100MHz',
          u'nrarfcn': 2059000,
          u'physCellId': 50,
          u'technology': u'TDD'}]
        """
        cell_data = self._api_client.execute_customer_procedure("getCellList", {}, timeout)
        cell_data_message = cell_data.get(self._provided_content.request_message)
        cell_rat_info = cell_data_message.get(self._provided_content.cells_information)

        if cell_rat_info is None:
            raise DataNotAvailable("Cell data has not been provided by M-Plane.")

        rat_cell_data = cell_rat_info.get(cell_type)

        if rat_cell_data is None:
            raise DataNotAvailable("RAT Cell information has not been provided by M-Plane.")

        return cell_data if detailed_output else rat_cell_data

    def get_subcells_info(self, timeout=10):
        """
        Get Subcell data of all available cells. Only supports 5G (NR).

        :param int timeout: Timeout for the operation.
        :raise DataNotAvailable: If 5G subcell data is not provided by M-Plane.
        :raise DataInconsistent: If 5G ADMIN or OAM Node-B provided information is incorrect with expected or faulty.
        :return dict: Dict structure where Key is cell group name and Value is structure with Realtime and Hardware
                                information for cells.

        Example of returned data:

        ::

        {
            u'NRCELLGRP-0': {
                u'NRCELL-1': {
                    'NRCELL_L': {
                         'distName': '/MRBTS-1/RAT-1/NRTS-1/NRBTS_L-1/NRCELL_L-1',
                         'parameters': {'lcrId': 1,
                                        'nrCellIdentity': 16385,
                                        'nrCellgrpDN': u'/MRBTS-1/RAT-1/NRTS-1/NRBTS_L-1/NRCELLGRP_L-0',
                                        'stateInfo': {'administrativeState': u'Locked',
                                                      'availabilityStatus': None,
                                                      'operationalState': u'Disabled',
                                                      'usageState': u'Idle'}
                                        }
                    },
                    'NRCELL_R': {
                          'distName': '/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/NRBTS_R-1/NRCELL_R-1',
                          'parameters': {'availabilityStatus': None,
                                         'bbModDNList': [],
                                         'frRefList': [],
                                         'nrCellIdentity': None,
                                         'operationalState': u'disabled',
                                         'proceduralStatus': None,
                                         'stateInfo': {'administrativeState': u'Unlocked',
                                                       'availabilityStatus': u'Failed',
                                                       'blockingState': u'Unblocked',
                                                       'operationalState': u'Disabled',
                                                       'usageState': u'Idle'}
                                        }
                    }
                }
            }
        }

        """
        bts_info = self.get_bts_info(timeout=timeout)

        if not bts_info.get("cellsGroup"):
            raise DataNotAvailable("Cell Group data containing subcell information was not provided by Node B OAM.")

        try:
            cell_groups_info = self.__get_cell_data_structure(cell_group_info=bts_info["cellsGroup"])
        except (KeyError, TypeError) as e:
            error_msg = "BTS cellsGroup information provided by OAM Node-B is inconsistent, or faulty. Error {}"
            raise DataInconsistent(error_msg.format(e))

        nr_cells_runtime = self.__get_infomodel_objects(
            object_type=NrCellRuntime,
            object_class_name="NRCELL_R",
            timeout=timeout)
        nr_cells_hardware = self.__get_infomodel_objects(
            object_type=NrCellHardware,
            object_class_name="NRCELL_L",
            timeout=timeout)

        self.__assign_hardware_cells(nr_cells_hardware, cell_groups_info)
        self.__assign_realtime_cells(nr_cells_runtime, cell_groups_info)

        return cell_groups_info

    def __assign_hardware_cells(self, nr_cells_hardware, cell_groups_info):
        for nr_cell in nr_cells_hardware:
            cell_group = InfoModelDistName(dist_name=nr_cell.nr_cellgrp_dn)
            self.__put_nr_cell_in_group(nr_cell, cell_groups_info, cell_group_name=cell_group.conf_name)

    def __assign_realtime_cells(self, nr_cells_runtime, cell_groups_info):
        for nr_cell in nr_cells_runtime:
            cell_group_name = self.__get_group_name_for_cell(
                cell_name=nr_cell.conf_name,
                cell_groups_info=cell_groups_info)
            if cell_group_name is None:
                error_msg = "Cell {cell_dist_name} returned by Node-B OAM, does not belong to any cell group"
                raise DataInconsistent(error_msg.format(cell_dist_name=nr_cell.dist_name))
            self.__put_nr_cell_in_group(nr_cell, cell_groups_info, cell_group_name=cell_group_name)

    def __get_group_name_for_cell(self, cell_name, cell_groups_info):
        for group_name, group_cells in cell_groups_info.items():
            if cell_name in group_cells:
                return group_name

    def __put_nr_cell_in_group(self, cell, cell_info, cell_group_name):
        cell_info[cell_group_name][cell.conf_name][cell.class_name] = cell.to_dict()

    def __get_cell_data_structure(self, cell_group_info):
        structure = {}
        for cell_group in cell_group_info:
            cell_group_name = cell_group["name"]

            if cell_group_name not in structure:
                structure[cell_group_name] = {}

            for cell_name in cell_group["nrCellList"]:
                structure[cell_group_name][cell_name] = {}

        return structure

    def __get_infomodel_objects(self, object_type, object_class_name, timeout):
        objects = []
        object_datas = self.get_managed_objects(class_name=object_class_name, timeout=timeout)

        for data in object_datas:
            objects.append(object_type.from_object_dict(data=data))
        return objects

    def get_subcells_status(self, timeout=10):
        """
        Get statuses for all subcells in cell groups.

        :param int timeout: Timeout for the operation.
        :raise DataNotAvailable: If 5G subcell data is not provided by M-Plane.
        :raise DataInconsistent: If 5G ADMIN or OAM Node-B provided information is incorrect with expected or faulty.
        :return dict: Dict structure where Key is cell group name and Value is structure with Realtime and Hardware
                                status names for cells.

        Example

        ::

        {
            u'NRCELLGRP-0': {
                u'NRCELL-1': {
                    'NRCELL_L': {
                        'administrativeState': u'Locked',
                        'availabilityStatus': None,
                        'operationalState': u'Disabled',
                        'usageState': u'Idle'
                    },
                    'NRCELL_R': {
                        'administrativeState': u'Unlocked',
                        'availabilityStatus': u'Failed',
                        'blockingState': u'Unblocked',
                        'operationalState': u'Disabled',
                        'usageState': u'Idle'
                    }
                }
            }
        }
        """
        cells_info = self.get_subcells_info(timeout=timeout)
        cells_statuses = {}

        try:
            for cell_group_name, cell_group_data in cells_info.items():
                cells_statuses[cell_group_name] = {}
                for cell_name, cell_data in cell_group_data.items():
                    cell_statuses = self.__get_statuses_for_cell(cell_data=cell_data)
                    cells_statuses[cell_group_name][cell_name] = cell_statuses

        except KeyError as e:
            raise DataInconsistent("Data provided by M-plane is inconsistent or faulty. Error {}".format(e))

        return cells_statuses

    def __get_statuses_for_cell(self, cell_data):
        cell_statuses = {}

        for cell_info_type, cell_type_data in cell_data.items():
            cell_statuses[cell_info_type] = cell_type_data["parameters"]["stateInfo"]

        return cell_statuses

    def get_gnsses_statuses(self, timeout=10):
        """
        Get statuses for all GNSSes.

        :param int timeout: Timeout for the operation.
        :return dict: Dictionary structure with data, where keys are GNSS names, values are dicts with statuses.
            More details: https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-getGpsInventoryList.html
        Example

        ::

            {
            'GNSSE_R-1':
                {
                    'administrativeState': 'Unlocked',
                    'availabilityStatus': 'PowerOff',
                    'operationalState': 'Disabled',
                    'usageState': 'Idle'
                }
            }
        """
        gps_inventory_list_payload = self._api_client.execute_customer_procedure("getGpsInventoryList", {}, timeout)
        gps_inventory_list_payload = gps_inventory_list_payload.get(self._provided_content.request_message)

        try:
            gnsse_list = gps_inventory_list_payload[self._provided_content.gnsse_information]

        except KeyError:
            error_desc = "Gnsse information has not been provided by M-Plane."
            raise DataNotAvailable(error_desc)

        gnsses_statuses = {}

        try:
            for gnss in gnsse_list:
                gnsses_statuses[gnss['name']] = gnss['stateInfo']

        except KeyError:
            raise DataInconsistent("Data provided by M-plane is inconsistent or faulty.")

        return gnsses_statuses

    def get_antennas(self, timeout=10):
        """
        Get antennas information from M-Plane (OAM).

        :param int timeout: Timeout for the operation.
        :raise DataNotAvailable: If radio module data is not provided by M-Plane.
        :return dict: Dict where key is radio module internal id shortened eg. 'RMOD_R-3, value is antenaUsageInfo.

        Example

        ::

            {
              'RMOD_R-1': [
              {
              'direction': 'TX/RX',
              'id':
                  {
                  'internal': '/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/RMOD_R-1/ANTL_R-5',
                  'runtime': 'MRBTS-10191/EQM_R-1/APEQM_R-1/RMOD_R-1/ANTL_R-5'
                  }
              },
              {
              'direction': 'TX/RX',
              'id':
                  {
                  'internal': '/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/RMOD_R-1/ANTL_R-7',
                  'runtime': 'MRBTS-10191/EQM_R-1/APEQM_R-1/RMOD_R-1/ANTL_R-7'
                  }
              }]
            }
        """
        bts_info = self.get_bts_info(timeout=timeout)

        try:
            radio_modules_data = bts_info[self._provided_content.radio_modules_information]
            rmod_data = radio_modules_data['rmod']

        except KeyError:
            raise DataNotAvailable("Radio module information has not been provided by M-Plane.")

        antennas_info = self.__get_info_for_modules(rmod_data, 'antenaUsageInfo', antennas=True)

        return antennas_info

    def get_rmod_fan_info(self, timeout=10):
        """
        Get fan statuses for rmod information from M-Plane (OAM).

        :param int timeout: Timeout for the operation.
        :raise DataNotAvailable: If module data is not provided by M-Plane.
        :return dict: Dict where key is module internal id shortened eg. 'RMOD_R-3', value is fanStatus dict.

        Example

        ::

            {
            'RMOD_R-1':
                {
                'availabilityStatus': 'Online',
                'operationalState': 'Enabled',
                'usageState': 'Idle'
                }
            }
        """
        fan_location = (self._provided_content.radio_modules_information, 'rmod')

        return self._get_fan_info(fan_location, timeout)

    def get_cabinets_fan_info(self, timeout=10):
        """
        Get fan statuses for cabinets information from M-Plane (OAM).

        :param int timeout: Timeout for the operation.
        :raise DataNotAvailable: If module data is not provided by M-Plane.
        :return dict: Dict where key is module internal id shortened eg. 'CABINET_1', value is fanStatus dict.

        Example

        ::

            {
            'CABINET_R-2':{
                'fans': [
                    {'name': 'FAN_R-1',
                     'distName': 'MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/CABINET_R-2/FAN_R-2',
                     'stateInfo': {
                         'availabilityStatus': 'Online',
                         'operationalState': 'Enabled',
                         'usageState': 'Idle'
                         }
                    }
            },
            'CABINET_R-1':{
                'fans': []
                }
            }
        """
        fan_location = (self._provided_content.cabinets_information,)
        return self._get_fan_info(fan_location, timeout)

    def _get_fan_info(self, locations, timeout):
        bts_info = self.get_bts_info(timeout=timeout)
        try:
            for location in locations:
                bts_info = bts_info[location]
            modules_data = bts_info
        except (AttributeError, KeyError):
            raise DataNotAvailable("information has not been provided by M-Plane.")

        return self.__get_fans_statuses(modules_data)

