    def get_smod_position(self, timeout=10):
        """
        Get SMOD posistion.

        :param int timeout: Time to wait for positive procedure result.

        :return str: SMOD position

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-getSmodPosition.html
        """

        reply = self._api_client.execute_infomodel_request("getSmodPosition", {}, timeout)
        if isinstance(reply, dict):
            smod = [reply[s][0] for s in reply]
            for item in smod:
                if search_recursively(item, "activeRole") == "primary":
                    get_val = search_recursively(item, "positionOnShelf")
                    break
                else:
                    get_val = search_recursively(reply, "positionOnShelf")
            result = get_val.split("Side")[0] if get_val.startswith(
                "left") or get_val.startswith("right") else get_val
            return result
        else:
            return reply

